{"name":"洛天依","picUrl":"http://p4.music.126.net/2dJ9Fo7HfkRExyICXG_t3g==/109951167677450486.jpg","id":"7705278762"},
//歌单参数示例
//齐全的参数直观好看，但是在源注释填写太耗地方，建议放到本地txt填写。
{
//必填，书籍名称。
//更改参数后需要重新加入书架。
"name": "歌单示例1",
//可选，作者名称
//无参数默认为"🎶 简单音乐"
"creator":{"nickname":"@Thomas喲"},
//可选，歌单分类
"tags": ["歌单示例","轻松","愉快","悠然"],
//可选，歌单简介
"description": "歌单示例1是简单音乐_书源里面的默认自定义歌单，整个歌单共有 2首歌？由@Thomas喲分享。",
//可选，歌单封面链接
//无参数会启用默认封面
"picUrl": "",
//必填，歌曲列表
"songs":[
{"name":"贝加尔湖畔","ar":{"name":"日光流年"},"dt":"245500","type":"netease","id":"1972299911"},
{"name":"夏日之上","ar":{"name":"战双帕弥什、熊子、ANK"},"dt":"204295","type":"netease","id":"1965889805"},
]},
//txt按照歌单示例1的格式填写
String(java.importScript('/storage/emulated/0/自定义路径/歌单示例2.txt')),
]//自定义歌单_结束

